testsCVoteRegistrationDenies: list[SignTxTestCase] = [
    SignTxTestCase(
        name="CIP15_registration_with_delegations_rejected",
        tx=Transaction(
            network=Mainnet,
            inputs=[inputs["utxoShelley"]],
            outputs=[outputs["internalBaseWithStakingPath"]],
            auxiliaryData=TxAuxiliaryData(
                TxAuxiliaryDataType.CIP36_REGISTRATION,
                TxAuxiliaryDataCIP36(
                    CIP36VoteRegistrationFormat.CIP_15,
                    "m/1852'/1815'/0'/2/0",
                    destinations["internalBaseWithStakingPath"],
                    1454448,
                    "4b19e27ffc006ace16592311c4d2f0cafc255eaa47a6178ff540c0a46d07027c",
                    delegations=[
                        CIP36VoteDelegation(
                            type=CIP36VoteDelegationType.KEY,
                            votingKeyPath="4b19e27ffc006ace16592311c4d2f0cafc255eaa47a6178ff540c0a46d07027c",
                            weight=1,
                        ),
                    ],
                ),
            ),
        ),
        signingMode=TransactionSigningMode.ORDINARY,
        expected_swo=StatusWord.SWO_CVOTE_AUX_DATA_PARSING_FAIL,
        deny_before_review=True,
        unsuitable_in_ragger_reason=None,
    ),
    SignTxTestCase(
        name="CIP36_registration_with_staking_key_as_raw_pubkey",
        tx=Transaction(
            network=Mainnet,
            inputs=[inputs["utxoShelley"]],
            outputs=[outputs["internalBaseWithStakingPath"]],
            auxiliaryData=TxAuxiliaryData(
                TxAuxiliaryDataType.CIP36_REGISTRATION,
                TxAuxiliaryDataCIP36(
                    CIP36VoteRegistrationFormat.CIP_36,
                    "4b19e27ffc006ace16592311c4d2f0cafc255eaa47a6178ff540c0a46d07027c",
                    destinations["internalBaseWithStakingPath"],
                    1454448,
                    "4b19e27ffc006ace16592311c4d2f0cafc255eaa47a6178ff540c0a46d07027c",
                    votingPurpose=0,
                ),
            ),
        ),
        signingMode=TransactionSigningMode.ORDINARY,
        expected_swo=StatusWord.SWO_SECURITY_CONDITION_NOT_SATISFIED,
        deny_before_review=True,
        unsuitable_in_ragger_reason=None,
    ),
    SignTxTestCase(
        name="CIP36_registration_with_invalid_format_byte",
        tx=Transaction(
            network=Mainnet,
            inputs=[inputs["utxoShelley"]],
            outputs=[outputs["internalBaseWithStakingPath"]],
            auxiliaryData=TxAuxiliaryData(
                TxAuxiliaryDataType.CIP36_REGISTRATION,
                TxAuxiliaryDataCIP36(
                    cast(CIP36VoteRegistrationFormat, 3),  # invalid: only CIP_15=1 and CIP_36=2 are valid
                    "m/1852'/1815'/0'/2/0",
                    destinations["internalBaseWithStakingPath"],
                    1454448,
                    "4b19e27ffc006ace16592311c4d2f0cafc255eaa47a6178ff540c0a46d07027c",
                ),
            ),
        ),
        signingMode=TransactionSigningMode.ORDINARY,
        expected_swo=StatusWord.SWO_CVOTE_AUX_DATA_PARSING_FAIL,
        deny_before_review=True,
        unsuitable_in_ragger_reason=None,
    ),
    SignTxTestCase(
        name="CIP36_registration_with_bad_staking_key_path",
        tx=Transaction(
            network=Mainnet,
            inputs=[inputs["utxoShelley"]],
            outputs=[outputs["internalBaseWithStakingPath"]],
            auxiliaryData=TxAuxiliaryData(
                TxAuxiliaryDataType.CIP36_REGISTRATION,
                TxAuxiliaryDataCIP36(
                    CIP36VoteRegistrationFormat.CIP_36,
                    "m/1852'/1815'/0'/3/0",  # chain=3, not a valid staking key path (must be 2)
                    destinations["internalBaseWithStakingPath"],
                    1454448,
                    "4b19e27ffc006ace16592311c4d2f0cafc255eaa47a6178ff540c0a46d07027c",
                    votingPurpose=0,
                ),
            ),
        ),
        signingMode=TransactionSigningMode.ORDINARY,
        expected_swo=StatusWord.SWO_SECURITY_CONDITION_NOT_SATISFIED,
        deny_before_review=True,
        unsuitable_in_ragger_reason=None,
    ),
    SignTxTestCase(
        name="CIP36_registration_with_payment_destination_network_mismatch",
        tx=Transaction(
            network=Mainnet,
            inputs=[inputs["utxoShelley"]],
            outputs=[outputs["internalBaseWithStakingPath"]],
            auxiliaryData=TxAuxiliaryData(
                TxAuxiliaryDataType.CIP36_REGISTRATION,
                TxAuxiliaryDataCIP36(
                    CIP36VoteRegistrationFormat.CIP_36,
                    "m/1852'/1815'/0'/2/0",
                    destinations["externalShelleyBaseKeyhashScripthashFakenet"],  # FakeNet addr on Mainnet tx
                    1454448,
                    "4b19e27ffc006ace16592311c4d2f0cafc255eaa47a6178ff540c0a46d07027c",
                    votingPurpose=0,
                ),
            ),
        ),
        signingMode=TransactionSigningMode.ORDINARY,
        expected_swo=StatusWord.SWO_SECURITY_CONDITION_NOT_SATISFIED,
        deny_before_review=True,
        unsuitable_in_ragger_reason=None,
    ),
    SignTxTestCase(
        name="CIP36_registration_with_vote_key_path_wrong_purpose",
        tx=Transaction(
            network=Mainnet,
            inputs=[inputs["utxoShelley"]],
            outputs=[outputs["internalBaseWithStakingPath"]],
            auxiliaryData=TxAuxiliaryData(
                TxAuxiliaryDataType.CIP36_REGISTRATION,
                TxAuxiliaryDataCIP36(
                    CIP36VoteRegistrationFormat.CIP_36,
                    "m/1852'/1815'/0'/2/0",
                    destinations["internalBaseWithStakingPath"],
                    1454448,
                    "m/1852'/1815'/0'/0/0",  # Shelley purpose, not CVote purpose (1694')
                    votingPurpose=0,
                ),
            ),
        ),
        signingMode=TransactionSigningMode.ORDINARY,
        expected_swo=StatusWord.SWO_SECURITY_CONDITION_NOT_SATISFIED,
        deny_before_review=True,
        unsuitable_in_ragger_reason=None,
    ),
]

